'use client';
import {useEffect,useState} from 'react';

type Status='Improving'|'Plateau'|'Declining'|'No data';
type Client={name:string;initials:string;status:Status;score:number;note:string;strength:string;volume:string;adherence:string;planned:number;done:number;program:string};
type Exercise={name:string;icon:string;sets:number;reps:string;kg:number;rest:number;group?:string};
type Program={id:number;name:string;days:number;clients:number;exercises:Exercise[]};
type Message={from:'pt'|'athlete';text:string;time:string};
type CommunityPost={author:string;initials:string;role:'pt'|'athlete';text:string;time:string;reactions:number;system?:boolean};
type DietPlan={file:string;updated:string;validUntil:string;author:string};
type View='landing'|'pt-home'|'stats'|'pt-calendar'|'pt-community'|'community'|'pt-diets'|'clients'|'client'|'programs'|'program-editor'|'athlete-home'|'calendar'|'messages'|'diet'|'sheet'|'picker'|'workout'|'progress'|'summary';
type ScheduleState='planned'|'completed'|'skipped';

const baseExercises:Exercise[]=[
 {name:'Lat machine',icon:'↧',sets:3,reps:'8–10',kg:55,rest:90,group:'Superserie A'},{name:'Chest press',icon:'↔',sets:3,reps:'8–10',kg:60,rest:90,group:'Superserie A'},
 {name:'Military press',icon:'↑',sets:3,reps:'8',kg:35,rest:90},{name:'Squat',icon:'⌄',sets:3,reps:'8',kg:80,rest:120},
 {name:'Tricipiti ai cavi',icon:'⇣',sets:3,reps:'12',kg:25,rest:60,group:'Superserie B'},{name:'Bicipiti ai cavi',icon:'⌁',sets:3,reps:'12',kg:20,rest:60,group:'Superserie B'}
];
const exerciseTips:Record<string,string>={'Lat machine':'Petto alto, porta i gomiti verso i fianchi.','Chest press':'Scapole ferme e polsi allineati.','Military press':'Addome attivo, non inarcare la schiena.','Squat':'Ginocchia in linea con le punte dei piedi.','Tricipiti ai cavi':'Gomiti fermi vicino al busto.','Bicipiti ai cavi':'Non oscillare: muovi solo gli avambracci.'};
const starterPosts:CommunityPost[]=[{author:'Luca Bianchi',initials:'LB',role:'pt',text:'Questa settimana concentriamoci sull’esecuzione: meno peso, più controllo. Buon allenamento squadra!',time:'Oggi · 08:15',reactions:8},{author:'Giulia Verdi',initials:'GV',role:'athlete',text:'Nuovo record nello squat: 95 kg! 🔥',time:'Oggi · 10:42',reactions:12},{author:'Progressì',initials:'P',role:'pt',text:'Marta ha completato una settimana perfetta: 4 allenamenti su 4.',time:'Ieri · 19:30',reactions:6,system:true},{author:'Marco Rossi',initials:'MR',role:'athlete',text:'Qualcuno si allena domani verso le 18?',time:'Ieri · 18:06',reactions:3}];
const defaultDiet:DietPlan={file:'Piano alimentare · Settembre.pdf',updated:'18 settembre',validUntil:'15 ottobre',author:'Dott.ssa Laura Riva · Biologa nutrizionista'};
const starterPrograms:Program[]=[
 {id:1,name:'Total Body · Base',days:3,clients:8,exercises:baseExercises},{id:2,name:'Ricondizionamento',days:2,clients:4,exercises:baseExercises.slice(0,4)},
 {id:3,name:'Performance 4 giorni',days:4,clients:3,exercises:baseExercises}
];
const starterClients:Client[]=[
 ['Marco Rossi','MR','Plateau',78,'Chest press stabile da 5 settimane','+2,1%','+1,2%','91%',3,2,'Total Body · Base'],
 ['Andrea Bianchi','AB','Declining',61,'Performance −8% negli ultimi 3 workout','−8,0%','−6,0%','68%',3,1,'Total Body · Base'],
 ['Giulia Verdi','GV','Improving',91,'Squat +12% nelle ultime 6 settimane','+12,0%','+15,4%','97%',4,4,'Performance 4 giorni'],
 ['Sara Conti','SC','Improving',86,'3 PR questo mese','+8,7%','+9,1%','94%',3,3,'Total Body · Base'],
 ['Matteo Romano','MR','Improving',83,'Progressione costante','+6,2%','+8,0%','88%',3,2,'Total Body · Base'],
 ['Elena Ricci','ER','Plateau',73,'Volume stabile da 4 settimane','+0,8%','+0,4%','90%',2,2,'Ricondizionamento'],
 ['Lorenzo Gallo','LG','Declining',58,'Ultimo workout 7 giorni fa','−4,2%','−7,1%','61%',3,1,'Total Body · Base'],
 ['Marta Leone','ML','Improving',88,'Stacco +10% in 8 settimane','+9,8%','+11,2%','95%',4,4,'Performance 4 giorni'],
 ['Davide Moretti','DM','No data',0,'In attesa del primo workout','—','—','—',2,0,'Ricondizionamento'],
 ['Anna Ferri','AF','Improving',84,'Ottima regolarità','+5,9%','+7,2%','98%',3,3,'Total Body · Base'],
 ['Paolo Greco','PG','Plateau',71,'Carichi invariati da 3 settimane','+0,3%','+1,0%','82%',3,2,'Total Body · Base'],
 ['Chiara Fontana','CF','Improving',89,'5 PR questo mese','+10,1%','+12,8%','96%',4,4,'Performance 4 giorni']
].map(x=>({name:x[0] as string,initials:x[1] as string,status:x[2] as Status,score:x[3] as number,note:x[4] as string,strength:x[5] as string,volume:x[6] as string,adherence:x[7] as string,planned:x[8] as number,done:x[9] as number,program:x[10] as string}));
const weeks=[
 {date:'19 AGO',done:2,planned:3,volume:'6.820 kg',score:72},{date:'26 AGO',done:3,planned:3,volume:'7.140 kg',score:75},
 {date:'2 SET',done:3,planned:3,volume:'7.510 kg',score:79},{date:'9 SET',done:2,planned:3,volume:'7.840 kg',score:82}
];
const load=<T,>(key:string,fallback:T):T=>{if(typeof window==='undefined')return fallback;try{return JSON.parse(localStorage.getItem(key)||'null')||fallback}catch{return fallback}};

export default function App(){
 const[view,setView]=useState<View>('landing'),[clients,setClients]=useState<Client[]>(()=>load('progressi-clients',starterClients)),[programs,setPrograms]=useState<Program[]>(()=>load('progressi-programs',starterPrograms));
 const[showIntro,setShowIntro]=useState(true);
 const[selectedClient,setSelectedClient]=useState(0),[selectedProgram,setSelectedProgram]=useState<Program|null>(null),[filter,setFilter]=useState('Tutti'),[modal,setModal]=useState(false);
 const[weekDays,setWeekDays]=useState(()=>load('progressi-days',['Lunedì','Mercoledì','Venerdì'])),[schedule,setSchedule]=useState<ScheduleState[]>(()=>load('progressi-schedule',['completed','planned','planned'])),[completed,setCompleted]=useState<number[]>([]),[exercise,setExercise]=useState(0),[series,setSeries]=useState<number[]>(()=>baseExercises.map(()=>1)),[kg,setKg]=useState(55),[reps,setReps]=useState(9),[seconds,setSeconds]=useState(0),[toast,setToast]=useState('');
 const[messages,setMessages]=useState<Message[]>(()=>load('progressi-messages',[{from:'pt',text:'Ciao Marco, venerdì la palestra sarà molto affollata. Riesci a spostare l’allenamento a sabato mattina?',time:'09:42'},{from:'athlete',text:'Sì, per me va bene alle 10:00.',time:'09:48'}]));
 const[posts,setPosts]=useState<CommunityPost[]>(()=>load('progressi-community',starterPosts)),[diets,setDiets]=useState<Record<string,DietPlan>>(()=>load('progressi-diets',{'Marco Rossi':defaultDiet}));
 useEffect(()=>{if(seconds<1)return;const timer=setInterval(()=>setSeconds(v=>v-1),1000);return()=>clearInterval(timer)},[seconds]);
 const go=(next:View)=>{setView(next);scrollTo(0,0)};
 const persistClients=(next:Client[])=>{setClients(next);localStorage.setItem('progressi-clients',JSON.stringify(next))};
 const persistPrograms=(next:Program[])=>{setPrograms(next);localStorage.setItem('progressi-programs',JSON.stringify(next))};
 const notify=(text:string)=>{setToast(text);setTimeout(()=>setToast(''),2200)};
 const sendMessage=(from:'pt'|'athlete',text:string)=>{const next=[...messages,{from,text,time:new Date().toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})}];setMessages(next);localStorage.setItem('progressi-messages',JSON.stringify(next));notify('Messaggio inviato')};
 const publishPost=(role:'pt'|'athlete',text:string)=>{const next=[{author:role==='pt'?'Luca Bianchi':'Marco Rossi',initials:role==='pt'?'LB':'MR',role,text,time:'Adesso',reactions:0},...posts];setPosts(next);localStorage.setItem('progressi-community',JSON.stringify(next));notify('Pubblicato nella community')};
 const saveDiet=(name:string,file:string)=>{const next={...diets,[name]:{file:file||'Nuovo piano alimentare.pdf',updated:'oggi',validUntil:'26 ottobre',author:'Professionista indicato nel documento'}};setDiets(next);localStorage.setItem('progressi-diets',JSON.stringify(next));notify('Piano alimentare condiviso')};
 const reset=()=>{localStorage.clear();setClients(starterClients);setPrograms(starterPrograms);setWeekDays(['Lunedì','Mercoledì','Venerdì']);setSchedule(['completed','planned','planned']);setMessages([]);setPosts(starterPosts);setDiets({'Marco Rossi':defaultDiet});setCompleted([]);setSeries(baseExercises.map(()=>1));setView('landing');setShowIntro(true);notify('Demo ripristinata')};
 if(showIntro)return <IntroTour finish={()=>{setShowIntro(false);setView('landing');scrollTo(0,0)}}/>;
 if(view==='landing')return <Landing go={go}/>;
 if(['athlete-home','calendar','community','messages','diet','sheet','progress'].includes(view))return <AthleteShell view={view} go={go} reset={reset}>{view==='athlete-home'?<AthleteHome go={go} client={clients[0]} schedule={schedule}/>:view==='calendar'?<Calendar days={weekDays} schedule={schedule} setDays={d=>{setWeekDays(d);localStorage.setItem('progressi-days',JSON.stringify(d))}} setSchedule={next=>{setSchedule(next);localStorage.setItem('progressi-schedule',JSON.stringify(next))}}/>:view==='community'?<Community posts={posts} role="athlete" publish={text=>publishPost('athlete',text)}/>:view==='messages'?<MessagesPage messages={messages} send={text=>sendMessage('athlete',text)}/>:view==='diet'?<AthleteDiet plan={diets['Marco Rossi']} go={go}/>:view==='sheet'?<AthleteSheet go={go}/>:<Progress/>}</AthleteShell>;
 if(view==='picker')return <Picker completed={completed} choose={i=>{setExercise(i);setKg(baseExercises[i].kg);setReps(Number(baseExercises[i].reps.split('–')[0]));go('workout')}} finish={()=>{const nextSchedule=[...schedule];nextSchedule[1]='completed';setSchedule(nextSchedule);localStorage.setItem('progressi-schedule',JSON.stringify(nextSchedule));persistClients(clients.map((c,i)=>i===0?{...c,done:Math.max(c.done,2)}:c));go('summary')}} go={go}/>;
 if(view==='workout'){const current=baseExercises[exercise],setNo=series[exercise],partner=current.group?baseExercises.findIndex((x,i)=>i!==exercise&&x.group===current.group):-1;const openExercise=(i:number)=>{setExercise(i);setKg(baseExercises[i].kg);setReps(Number(baseExercises[i].reps.split('–')[0]))};const finishSet=(rest:number)=>{const doneNow=setNo>=current.sets,nextSeries=[...series];if(!doneNow)nextSeries[exercise]=setNo+1;setSeries(nextSeries);const nextCompleted=doneNow?[...new Set([...completed,exercise])]:completed;if(doneNow)setCompleted(nextCompleted);if(partner>=0&&!nextCompleted.includes(partner)){openExercise(partner);setSeconds(15);return}if(doneNow){setSeconds(0);go('picker')}else setSeconds(rest)};return <Workout current={current} partner={partner>=0?baseExercises[partner]:undefined} setNo={setNo} kg={kg} reps={reps} setKg={setKg} setReps={setReps} complete={finishSet} seconds={seconds} skip={()=>setSeconds(0)} go={go}/>}
 if(view==='summary')return <Summary go={go}/>;
 const active=view==='pt-home'?'pt-home':view==='client'?'clients':view;
 return <PtShell active={active} go={go} reset={reset} add={()=>view==='programs'?openProgram():setModal(true)} toast={toast}>
  {view==='pt-home'?<PtToday clients={clients} schedule={schedule} days={weekDays} openClient={i=>{setSelectedClient(i);go('client')}}/>:view==='stats'?<PtStats clients={clients} openGroup={f=>{setFilter(f);go('clients')}} openClient={i=>{setSelectedClient(i);go('client')}}/>:view==='pt-calendar'?<PtCalendar clients={clients} schedule={schedule} openClient={i=>{setSelectedClient(i);go('client')}}/>:view==='pt-community'?<Community posts={posts} role="pt" publish={text=>publishPost('pt',text)}/>:view==='pt-diets'?<PtDiets clients={clients} diets={diets} save={saveDiet}/>:
   view==='clients'?<Clients clients={clients} filter={filter} setFilter={setFilter} open={i=>{setSelectedClient(i);go('client')}} add={()=>setModal(true)}/>:
   view==='client'?<ClientDetail client={clients[selectedClient]} schedule={selectedClient===0?schedule:undefined} days={weekDays} go={go} messages={messages} send={text=>sendMessage('pt',text)}/>:view==='programs'?<Programs programs={programs} create={openProgram} edit={p=>{setSelectedProgram(p);go('program-editor')}}/>:
   <ProgramEditor initial={selectedProgram} save={p=>{const exists=programs.some(x=>x.id===p.id);persistPrograms(exists?programs.map(x=>x.id===p.id?p:x):[...programs,p]);notify('Scheda salvata nella libreria');go('programs')}} cancel={()=>go('programs')}/>}
  {modal&&<ClientModal programs={programs} close={()=>setModal(false)} save={c=>{persistClients([...clients,c]);setModal(false);notify('Cliente creato e scheda assegnata')}}/>}
 </PtShell>;
 function openProgram(){setSelectedProgram(null);go('program-editor')}
}

function Logo(){return <span className="progressi-logo"><i><b/><b/><b/></i><strong>Progress<span>ì</span></strong></span>}
function IntroTour({finish}:{finish:()=>void}){const[step,setStep]=useState(0),[touchX,setTouchX]=useState(0);const slides=[{eyebrow:'IL TUO GIORNO, GIÀ CHIARO',title:'Sai chi arriva.\nPrima che arrivi.',copy:'Orari, presenze e assenze in un’unica agenda. Apri un cliente e intervieni subito.',kind:'agenda'},{eyebrow:'NON ASPETTARE CHE SI FERMINO',title:'I segnali giusti.\nAl momento giusto.',copy:'Progressi, plateau e aderenza diventano priorità chiare per il tuo lavoro.',kind:'insight'},{eyebrow:'DAL PROGRAMMA ALLA PALESTRA',title:'Tu programmi.\nProgressì li guida.',copy:'Schede flessibili, superserie intelligenti e feedback serie dopo serie.',kind:'workout'}];const next=()=>step<2?setStep(step+1):finish();const previous=()=>step>0&&setStep(step-1);const s=slides[step];return <main className={'intro-tour step-'+(step+1)} onTouchStart={e=>setTouchX(e.touches[0].clientX)} onTouchEnd={e=>{const delta=e.changedTouches[0].clientX-touchX;if(delta<-45)next();if(delta>45)previous()}}><header><Logo/><span>PER PERSONAL TRAINER</span></header><section className="intro-stage" aria-live="polite"><button className="intro-visual" onClick={next} aria-label="Vai allo step successivo"><IntroVisual kind={s.kind}/></button><div className="intro-copy"><p>{s.eyebrow}</p><h1>{s.title.split('\n').map((line,i)=><span key={line}>{line}{i===0&&<br/>}</span>)}</h1><h2>{s.copy}</h2></div></section><footer><div className="intro-dots" aria-label={`Step ${step+1} di 3`}>{slides.map((_,i)=><button key={i} onClick={()=>setStep(i)} className={i===step?'active':''} aria-label={`Vai allo step ${i+1}`}/>)}</div><button className="intro-next" onClick={next}>{step===2?'Inizia':'Continua'} <span>→</span></button><small>Scorri per continuare</small></footer></main>}
function IntroVisual({kind}:{kind:string}){if(kind==='agenda')return <div className="intro-device agenda-device"><div className="device-top"><i/><span>Oggi</span><b>7 SET</b></div><div className="agenda-hero"><small>ALLENAMENTI OGGI</small><strong>5</strong><span>1 completato · 1 saltato</span></div>{[['07:30','Giulia Verdi','Completato'],['12:30','Marco Rossi','In programma'],['17:00','Sara Conti','Saltato']].map((x,i)=><div className={'intro-session s'+i} key={x[0]}><time>{x[0]}</time><i>{x[1].split(' ').map(v=>v[0]).join('')}</i><span><b>{x[1]}</b><small>Total Body · Giorno {i+1}</small></span><em>{x[2]}</em></div>)}</div>;if(kind==='insight')return <div className="intro-device insight-device"><div className="insight-score"><span>PROGRESS SCORE</span><strong>82<small>/100</small></strong><em>↑ 10 punti</em><div className="intro-bars">{[35,43,39,57,66,72,88].map((h,i)=><i key={i} style={{height:h+'%'}}/>)}</div></div><div className="intro-alert"><i>!</i><span><small>RICHIEDE ATTENZIONE</small><b>Andrea è sotto il ritmo previsto</b><em>1 di 3 allenamenti completati</em></span><strong>→</strong></div><div className="intro-ai"><span>✦ COACH INSIGHT</span><p>“Scrivigli oggi: il calo di costanza anticipa quello di performance.”</p></div></div>;return <div className="intro-device workout-device"><div className="workout-phone"><div className="phone-status"><span>9:41</span><i>● ● ▰</i></div><small>SUPERSET A · SERIE 1 DI 3</small><div className="phone-icon">↧</div><h3>Lat machine</h3><p>Petto alto, gomiti verso i fianchi.</p><div className="next-exercise"><span>SUBITO DOPO</span><b>Chest press</b><em>15 sec</em></div><div className="phone-action">Completa e continua →</div></div><div className="flow-pill first"><i>1</i><span><b>Lat machine</b><small>8–10 reps</small></span></div><div className="flow-line"/><div className="flow-pill second"><i>2</i><span><b>Chest press</b><small>8–10 reps</small></span></div></div>}
function Landing({go}:{go:(v:View)=>void}){return <main className="landing"><nav><button className="brand" onClick={()=>go('landing')}><Logo/></button><div className="nav-actions"><button className="quiet" onClick={()=>go('athlete-home')}>Vista atleta</button><button className="nav-cta" onClick={()=>go('pt-home')}>Apri la demo</button></div></nav><section className="hero"><div className="hero-copy"><div className="pill"><i/> Intelligence che porta risultati</div><h1>Progressi chiari.<br/><em>Decisioni migliori.</em></h1><p>Gli atleti registrano ogni serie in pochi secondi. Tu sai chi sta migliorando, chi si è fermato e chi ha bisogno di te.</p><div className="hero-actions"><button className="primary" onClick={()=>go('pt-home')}>Esplora come PT <span>→</span></button><button className="secondary" onClick={()=>go('athlete-home')}>Prova come atleta</button></div><div className="hero-proof"><span>✓ Nessuna registrazione</span><span>✓ Demo interattiva</span><span>✓ Dati realistici</span></div></div><DashboardPreview/></section><section className="cycle"><span>Programma</span><i>→</i><span>Allenati</span><i>→</i><span>Registra</span><i>→</i><span>Comprendi</span><i>→</i><strong>Progredisci</strong></section></main>}
function DashboardPreview(){return <div className="product-preview"><div className="window-bar"><b><Logo/></b><span>Panoramica</span><span>Clienti</span><span>Schede</span></div><div className="preview-head"><div><small>BUONGIORNO, LUCA</small><h2>La tua squadra, a colpo d&apos;occhio.</h2></div></div><div className="metric-grid"><div className="metric"><span>CLIENTI</span><strong>12</strong><small>attivi</small></div><div className="metric highlight"><span>IN PROGRESSO</span><strong>58%</strong><small>7 clienti</small></div><div className="metric"><span>ATTENZIONE</span><strong>5</strong><small>plateau o calo</small></div></div><div className="attention">{starterClients.slice(0,3).map(c=><article key={c.name}><i className="avatar">{c.initials}</i><div><strong>{c.name}</strong><small>{c.note}</small></div><StatusPill value={c.status}/></article>)}</div></div>}

function PtShell({active,go,reset,add,toast,children}:{active:string;go:(v:View)=>void;reset:()=>void;add:()=>void;toast:string;children:React.ReactNode}){return <main className="coach-app"><aside><button className="brand" onClick={()=>go('landing')}><Logo/></button><p>SPAZIO COACH</p>{[['pt-home','◷','Oggi'],['pt-calendar','□','Calendario'],['pt-community','◎','Community'],['pt-diets','◇','Diete'],['stats','↗','Statistiche'],['clients','♙','Clienti'],['programs','▦','Schede']].map(x=><button key={x[0]} className={active===x[0]?'active':''} onClick={()=>go(x[0] as View)}><i>{x[1]}</i>{x[2]}</button>)}<div className="aside-bottom"><button onClick={()=>go('athlete-home')}>⇄ Vista atleta</button><button onClick={reset}>↻ Reset demo</button></div></aside><div className="coach-main"><header><span className="demo-badge">DEMO</span><button className="add-btn" onClick={add}>＋ {active==='programs'?'Nuova scheda':'Aggiungi cliente'}</button><i className="coach-avatar">LB</i></header>{children}</div>{toast&&<div className="toast">✓ {toast}</div>}</main>}
function PtToday({clients,schedule,days,openClient}:{clients:Client[];schedule:ScheduleState[];days:string[];openClient:(i:number)=>void}){const skipped=schedule.includes('skipped');const sessions=[{i:2,time:'07:30',state:'completed',label:'Completato'},{i:0,time:'12:30',state:skipped?'skipped':'planned',label:skipped?'Saltato':'In programma'},{i:3,time:'17:00',state:'planned',label:'In programma'},{i:5,time:'18:30',state:'planned',label:'In programma'},{i:1,time:'20:00',state:'risk',label:'Da confermare'}];return <section className="coach-page today-page"><p className="eyebrow">DOMENICA · 7 SETTEMBRE</p><h1>Oggi in palestra</h1><p className="lede">{sessions.length} clienti programmati · {sessions.filter(x=>x.state==='completed').length} completato · {sessions.filter(x=>x.state==='skipped').length} saltato</p><div className="today-summary"><div><span>ALLENAMENTI OGGI</span><b>{sessions.length}</b></div><div><span>COMPLETATI</span><b>1</b></div><div className={skipped?'red':''}><span>SALTATI</span><b>{skipped?1:0}</b></div><div><span>ANCORA PREVISTI</span><b>{sessions.filter(x=>x.state==='planned'||x.state==='risk').length}</b></div></div><div className="schedule-board"><div className="schedule-head"><span>ORARIO</span><span>CLIENTE E PROGRAMMA</span><span>STATO</span></div>{sessions.map(s=>{const c=clients[s.i];return <button className={'session '+s.state} onClick={()=>openClient(s.i)} key={c.name}><time>{s.time}</time><i className="avatar">{c.initials}</i><span><b>{c.name}</b><small>{c.program} · Allenamento giorno {s.i%3+1}</small></span><em>{s.label}</em><strong>→</strong></button>})}</div><div className="today-bottom"><div><p className="eyebrow">PROSSIMO</p><b>Marco Rossi · {days[1]}</b><small>Allenamento giorno 2 · 6 esercizi</small></div><div><p className="eyebrow">NOTA OPERATIVA</p><b>Andrea non ha confermato</b><small>Ultimo allenamento 7 giorni fa</small></div></div></section>}
function PtStats({clients,openGroup,openClient}:{clients:Client[];openGroup:(f:string)=>void;openClient:(i:number)=>void}){const counts={Improving:clients.filter(c=>c.status==='Improving').length,Plateau:clients.filter(c=>c.status==='Plateau').length,Declining:clients.filter(c=>c.status==='Declining').length};return <section className="coach-page"><p className="eyebrow">STATISTICHE · ULTIME 8 SETTIMANE</p><h1>Andamento clienti</h1><p className="lede">Progressi, plateau e aderenza in un solo sguardo.</p><div className="coach-metrics clickable"><button onClick={()=>openGroup('Tutti')}><span>CLIENTI</span><b>{clients.length}</b><small>Vedi tutti →</small></button><button className="green" onClick={()=>openGroup('Improving')}><span>IN MIGLIORAMENTO</span><b>{counts.Improving}</b><small>Apri gruppo →</small></button><button onClick={()=>openGroup('Plateau')}><span>PLATEAU</span><b>{counts.Plateau}</b><small>Apri gruppo →</small></button><button className="red" onClick={()=>openGroup('Declining')}><span>IN CALO</span><b>{counts.Declining}</b><small>Apri gruppo →</small></button></div><div className="stats-panels"><article><div><p className="eyebrow">ADERENZA MEDIA</p><h2>88%</h2><small>+4% rispetto al mese scorso</small></div><Bars/></article><article><p className="eyebrow">DISTRIBUZIONE</p>{[['In miglioramento',counts.Improving,'green'],['Plateau',counts.Plateau,'amber'],['In calo',counts.Declining,'red']].map(x=><div className="stat-bar" key={x[0]}><span>{x[0]}</span><i><b className={x[2] as string} style={{width:`${Number(x[1])/clients.length*100}%`}}/></i><strong>{x[1]}</strong></div>)}</article></div><div className="section-title"><div><h2>Richiedono attenzione</h2><p>Priorità basata su performance e presenza.</p></div></div><div className="attention-list">{clients.filter(c=>c.status==='Plateau'||c.status==='Declining').slice(0,4).map(c=><ClientRow key={c.name} c={c} click={()=>openClient(clients.indexOf(c))}/>)}</div></section>}
function PtCalendar({clients,schedule,openClient}:{clients:Client[];schedule:ScheduleState[];openClient:(i:number)=>void}){const days=['Lun 1','Mar 2','Mer 3','Gio 4','Ven 5','Sab 6','Dom 7'],[selected,setSelected]=useState(6);const plans=[[{i:1,t:'07:30'},{i:4,t:'13:00'},{i:6,t:'18:30'}],[{i:3,t:'08:00'},{i:7,t:'17:30'}],[{i:2,t:'07:30'},{i:5,t:'12:30'},{i:8,t:'19:00'}],[{i:0,t:'08:30'},{i:9,t:'18:00'}],[{i:4,t:'07:00'},{i:1,t:'13:00'},{i:10,t:'17:30'},{i:6,t:'20:00'}],[{i:7,t:'09:00'},{i:11,t:'11:00'}],[{i:2,t:'07:30'},{i:0,t:'12:30'},{i:3,t:'17:00'},{i:5,t:'18:30'},{i:1,t:'20:00'}]];const rows=plans[selected];return <section className="coach-page pt-calendar-page"><p className="eyebrow">SETTIMANA · 1–7 SETTEMBRE</p><h1>Calendario clienti</h1><p className="lede">Seleziona un giorno per vedere chi viene, a che ora e lo stato dell&apos;allenamento.</p><div className="coach-week">{days.map((d,i)=><button key={d} className={selected===i?'active':''} onClick={()=>setSelected(i)}><span>{d.split(' ')[0]}</span><b>{d.split(' ')[1]}</b><small>{plans[i].length} clienti</small></button>)}</div><div className="calendar-day-head"><div><p className="eyebrow">{days[selected].toUpperCase()} SETTEMBRE</p><h2>{rows.length} allenamenti programmati</h2></div><span><i/> In programma</span><span><i className="done"/> Completato</span><span><i className="skip"/> Saltato</span></div><div className="schedule-board">{rows.map((r,n)=>{const c=clients[r.i];const state=selected===6&&r.i===0&&schedule.includes('skipped')?'skipped':selected===6&&n===0?'completed':'planned';return <button className={'session '+state} onClick={()=>openClient(r.i)} key={`${r.i}-${r.t}`}><time>{r.t}</time><i className="avatar">{c.initials}</i><span><b>{c.name}</b><small>{c.program} · {c.planned} giorni/settimana</small></span><em>{state==='skipped'?'Saltato':state==='completed'?'Completato':'In programma'}</em><strong>→</strong></button>})}</div></section>}
function Clients({clients,filter,setFilter,open,add}:{clients:Client[];filter:string;setFilter:(x:string)=>void;open:(i:number)=>void;add:()=>void}){const shown=filter==='Tutti'?clients:clients.filter(c=>c.status===filter);return <section className="coach-page"><div className="program-heading"><div><p className="eyebrow">ATLETI</p><h1>I tuoi clienti</h1><p className="lede">Presenze, programmi e progressi in un solo posto.</p></div><button className="primary" onClick={add}>＋ Aggiungi cliente</button></div><div className="filters">{['Tutti','Improving','Plateau','Declining','No data'].map(f=><button key={f} className={filter===f?'active':''} onClick={()=>setFilter(f)}>{f}</button>)}</div><div className="client-table">{shown.map(c=><ClientRow key={c.name} c={c} click={()=>open(clients.indexOf(c))}/>)}</div></section>}
function ClientRow({c,click}:{c:Client;click:()=>void}){return <button className="client-row" onClick={click}><i className="avatar">{c.initials}</i><div><b>{c.name}</b><small>{c.program}</small><span className="attendance">Settimana: <strong>{c.done} di {c.planned}</strong> giorni</span></div><StatusPill value={c.status}/><div className="row-score"><small>SCORE</small><b>{c.score||'—'}</b></div><strong>→</strong></button>}
function StatusPill({value}:{value:Status}){return <span className={'status '+value.toLowerCase().replace(' ','-')}>{value}</span>}
function ClientDetail({client:c,schedule,days,go,messages,send}:{client:Client;schedule?:ScheduleState[];days:string[];go:(v:View)=>void;messages:Message[];send:(text:string)=>void}){const shownSchedule=schedule||Array.from({length:c.planned},(_,i)=>i<c.done?'completed':'planned' as ScheduleState),shownDays=schedule?days:['Lunedì','Mercoledì','Venerdì','Sabato'].slice(0,c.planned);return <section className="coach-page"><button className="back" onClick={()=>go('clients')}>← Tutti i clienti</button><div className="profile-title"><i className="avatar big">{c.initials}</i><div><h1>{c.name}</h1><StatusPill value={c.status}/></div><button className="secondary" onClick={()=>go('programs')}>Apri scheda →</button></div><div className="client-tabs"><button className="active">Panoramica</button><button onClick={()=>document.getElementById('client-calendar')?.scrollIntoView({behavior:'smooth'})}>Calendario</button><button onClick={()=>document.getElementById('conversation')?.scrollIntoView({behavior:'smooth'})}>Messaggi</button><button onClick={()=>document.getElementById('history')?.scrollIntoView({behavior:'smooth'})}>Storico</button><button onClick={()=>go('programs')}>Scheda</button></div><section id="client-calendar" className="pt-calendar"><div><p className="eyebrow">CALENDARIO CONDIVISO</p><h2>Programma della settimana</h2></div><div>{shownSchedule.map((state,i)=><article className={state} key={i}><i>{state==='completed'?'✓':state==='skipped'?'×':i+1}</i><span><b>Giorno {i+1} · {shownDays[i]}</b><small>{state==='completed'?'Allenamento completato':state==='skipped'?'Saltato dall’atleta':'Programmato'}</small></span><em>{state==='completed'?'Svolto':state==='skipped'?'Saltato':'Previsto'}</em></article>)}</div></section><Conversation name={c.name} role="pt" messages={messages} send={send}/><div className="detail-grid"><div className="detail-main"><div className="client-score"><span>PROGRESS SCORE <small>DEMO</small></span><b>{c.score||'—'}<em>/100</em></b><Spark/></div><div className="trend-cards four"><div><span>FORZA</span><b>{c.strength}</b></div><div><span>VOLUME</span><b>{c.volume}</b></div><div><span>COSTANZA</span><b>{c.adherence}</b></div><div><span>PRESENZE</span><b>{c.done}/{c.planned}</b></div></div><History/></div><aside className="insights"><article className="ai-card"><span>COACH INSIGHT ✨ <small>PREVIEW</small></span><p>“{c.name.split(' ')[0]} mantiene una buona costanza. La chest press è stabile da cinque settimane: valuta volume, intensità e recupero.”</p></article><h3>Segnali</h3>{shownSchedule.includes('skipped')&&<div className="signal-red">! <span>Allenamento saltato questa settimana</span></div>}<div>⚠️ <span>Chest press in plateau</span></div><div>🔥 <span>Squat in progressione</span></div><div>✓ <span>{c.done} allenamenti completati su {c.planned}</span></div></aside></div></section>}
function History(){return <section id="history" className="history-card"><div className="section-title"><div><h2>Storico completo</h2><p>Ultime 4 settimane</p></div></div>{weeks.map((w,i)=><article key={w.date}><div><b>{w.date}</b><small>Settimana {i+1}</small></div><span><strong>{w.done}/{w.planned}</strong> allenamenti</span><span><strong>{w.volume}</strong> volume</span><span><strong>{w.score}</strong> score</span><Spark/></article>)}</section>}

function Programs({programs,create,edit}:{programs:Program[];create:()=>void;edit:(p:Program)=>void}){return <section className="coach-page"><div className="program-heading"><div><p className="eyebrow">LIBRERIA SCHEDE</p><h1>Programmi di allenamento</h1></div><button className="primary" onClick={create}>＋ Nuova scheda</button></div><div className="program-library rich">{programs.map((p,i)=><article key={p.id}><i className="program-icon">{i+1}</i><div><b>{p.name}</b><small>{p.exercises.length} esercizi per giorno · ordine flessibile</small></div><strong>{p.days}× sett.</strong><span>{p.clients} clienti</span><button onClick={()=>edit(p)}>Modifica →</button></article>)}</div></section>}
function ProgramEditor({initial,save,cancel}:{initial:Program|null;save:(p:Program)=>void;cancel:()=>void}){const[name,setName]=useState(initial?.name||''),[days,setDays]=useState(initial?.days||3),[items,setItems]=useState<Exercise[]>(initial?.exercises||baseExercises),[newName,setNewName]=useState(''),[dragged,setDragged]=useState<number|null>(null);const addExercise=()=>{if(!newName.trim())return;setItems([...items,{name:newName,icon:'◆',sets:3,reps:'10–12',kg:20,rest:120,group:'Singolo'}]);setNewName('')};const update=(i:number,patch:Partial<Exercise>)=>setItems(items.map((v,n)=>n===i?{...v,...patch}:v));const move=(from:number,to:number)=>{if(from===to)return;const next=[...items],picked=next.splice(from,1)[0];next.splice(to,0,picked);setItems(next)};return <section className="coach-page editor-page"><button className="back" onClick={cancel}>← Libreria schede</button><div className="editor-head"><div><p className="eyebrow">{initial?'MODIFICA SCHEDA':'NUOVA SCHEDA'}</p><h1>{initial?'Aggiorna il programma':'Crea un nuovo programma'}</h1></div><button className="primary" onClick={()=>save({id:initial?.id||Date.now(),name:name||'Scheda senza nome',days,clients:initial?.clients||0,exercises:items})}>Salva scheda</button></div><div className="editor-grid"><div className="editor-main"><label className="big-field">Nome della scheda<input value={name} onChange={e=>setName(e.target.value)} placeholder="es. Total Body · Principianti"/></label><fieldset className="days-field"><legend>Giorni a settimana</legend><div>{[2,3,4,5].map(n=><button type="button" className={days===n?'active':''} onClick={()=>setDays(n)} key={n}>{n} giorni</button>)}</div></fieldset><div className="section-title"><div><h2>Esercizi del giorno</h2><p>Imposta serie, ripetizioni e collega gli esercizi in superserie o tri-serie.</p></div></div><div className="drag-hint"><i>↕</i> Trascina per cambiare l&apos;ordine consigliato · usa la stessa lettera per collegare gli esercizi</div><div className="exercise-editor sortable smart">{items.map((x,i)=><article draggable onDragStart={()=>setDragged(i)} onDragOver={e=>e.preventDefault()} onDrop={()=>{if(dragged!==null)move(dragged,i);setDragged(null)}} onDragEnd={()=>setDragged(null)} className={dragged===i?'dragging':''} key={`${x.name}-${i}`}><span className="drag-handle">⠿</span><i>{i+1}</i><input value={x.name} onChange={e=>update(i,{name:e.target.value})}/><label>Serie<input type="number" value={x.sets} onChange={e=>update(i,{sets:+e.target.value})}/></label><label>Ripetizioni<input value={x.reps} onChange={e=>update(i,{reps:e.target.value})} placeholder="8–10"/></label><label>Struttura<select value={x.group||'Singolo'} onChange={e=>update(i,{group:e.target.value})}>{['Singolo','Superserie A','Superserie B','Tri-serie A','Tri-serie B'].map(v=><option key={v}>{v}</option>)}</select></label><label>Recupero<input type="number" value={x.rest} onChange={e=>update(i,{rest:+e.target.value})}/></label><button onClick={()=>setItems(items.filter((_,n)=>n!==i))}>×</button></article>)}</div><div className="new-exercise"><input value={newName} onChange={e=>setNewName(e.target.value)} placeholder="Nome nuovo esercizio"/><button onClick={addExercise}>＋ Aggiungi</button></div></div><aside className="editor-summary"><span>RIEPILOGO</span><b>{name||'Nuova scheda'}</b><p>{days} giorni a settimana</p><p>{items.length} esercizi per allenamento</p><p>{items.reduce((n,x)=>n+x.sets,0)} serie totali</p><p>{items.filter(x=>x.group&&x.group!=='Singolo').length} esercizi collegati</p></aside></div></section>}
function ClientModal({programs,close,save}:{programs:Program[];close:()=>void;save:(c:Client)=>void}){const[name,setName]=useState(''),[program,setProgram]=useState(programs[0]);return <div className="modal-back"><form className="modal" onSubmit={e=>{e.preventDefault();const bits=name.split(' ');save({name,initials:bits.map(x=>x[0]).join('').slice(0,2).toUpperCase(),status:'No data',score:0,note:'In attesa del primo workout',strength:'—',volume:'—',adherence:'—',planned:program.days,done:0,program:program.name})}}><button type="button" className="modal-close" onClick={close}>×</button><p className="eyebrow">NUOVO CLIENTE</p><h2>Profilo e scheda</h2><label>Nome e cognome<input required value={name} onChange={e=>setName(e.target.value)} placeholder="es. Federico Costa"/></label><label>Email<input type="email" placeholder="federico@email.it"/></label><label>Scheda assegnata<select value={program.id} onChange={e=>setProgram(programs.find(p=>p.id===+e.target.value)||program)}>{programs.map(p=><option value={p.id} key={p.id}>{p.name} · {p.days} giorni</option>)}</select></label><div className="assigned-preview"><span>{program.name}</span><small>{program.days} giorni/settimana · {program.exercises.length} esercizi per giorno</small></div><button className="primary wide">Crea cliente e assegna</button></form></div>}

function AthleteShell({view,go,reset,children}:{view:View;go:(v:View)=>void;reset:()=>void;children:React.ReactNode}){return <main className="athlete-app"><header className="mobile-top"><button className="brand" onClick={()=>go('landing')}><Logo/></button><button className="circle-btn" onClick={reset}>↻</button></header>{children}<nav className="bottom-nav"><button className={view==='athlete-home'?'active':''} onClick={()=>go('athlete-home')}><i>⌂</i>Oggi</button><button className={view==='calendar'?'active':''} onClick={()=>go('calendar')}><i>□</i>Calendario</button><button className={view==='community'?'active':''} onClick={()=>go('community')}><i>◎</i>Community</button><button className={view==='diet'?'active':''} onClick={()=>go('diet')}><i>◇</i>Dieta</button><button className={view==='messages'?'active':''} onClick={()=>go('messages')}><i>✉</i>Messaggi</button><button className={view==='sheet'?'active':''} onClick={()=>go('sheet')}><i>▦</i>Scheda</button><button className={view==='progress'?'active':''} onClick={()=>go('progress')}><i>↗</i>Progressi</button><button onClick={()=>go('pt-home')}><i>⇄</i>PT</button></nav></main>}
function Community({posts,role,publish}:{posts:CommunityPost[];role:'pt'|'athlete';publish:(text:string)=>void}){const[text,setText]=useState(''),[liked,setLiked]=useState<number[]>([]);return <section className={role==='pt'?'coach-page community-page':'ath-home community-page'}><p className={role==='pt'?'eyebrow':'date'}>COMMUNITY PRIVATA · TEAM LUCA</p><h1>La squadra si muove insieme.</h1><p className="lede">Uno spazio riservato ai tuoi allievi. Il PT vede e modera ogni contenuto.</p><div className="community-summary"><div><span>QUESTA SETTIMANA</span><b>34 allenamenti</b><small>↑ 8% rispetto alla precedente</small></div><div className="community-faces">{['GV','MR','ML','SC'].map(x=><i key={x}>{x}</i>)}<strong>+8</strong></div></div><form className="community-compose" onSubmit={e=>{e.preventDefault();if(text.trim()){publish(text.trim());setText('')}}}><i>{role==='pt'?'LB':'MR'}</i><input value={text} onChange={e=>setText(e.target.value)} placeholder={role==='pt'?'Scrivi un annuncio alla squadra…':'Condividi qualcosa con la squadra…'}/><button>Pubblica</button></form><div className="community-feed">{posts.map((p,i)=><article className={p.system?'system':''} key={`${p.author}-${i}`}><i>{p.initials}</i><div><header><b>{p.author}</b>{p.role==='pt'&&<em>PT</em>}<small>{p.time}</small></header><p>{p.text}</p><footer><button className={liked.includes(i)?'liked':''} onClick={()=>setLiked(v=>v.includes(i)?v.filter(x=>x!==i):[...v,i])}>🔥 {p.reactions+(liked.includes(i)?1:0)}</button><button>Rispondi</button>{role==='pt'&&<button className="moderate">•••</button>}</footer></div></article>)}</div><p className="privacy-note">🔒 Community visibile solo agli allievi di Luca. Nessun dato sensibile viene condiviso automaticamente.</p></section>}
function PtDiets({clients,diets,save}:{clients:Client[];diets:Record<string,DietPlan>;save:(name:string,file:string)=>void}){return <section className="coach-page diets-page"><p className="eyebrow">PIANI ALIMENTARI</p><h1>Diete dei clienti</h1><p className="lede">Carica e aggiorna i documenti preparati dal professionista di riferimento.</p><div className="diet-client-list">{clients.slice(0,7).map(c=>{const plan=diets[c.name];return <article key={c.name}><i className="avatar">{c.initials}</i><span><b>{c.name}</b><small>{plan?`${plan.file} · aggiornato ${plan.updated}`:'Nessun piano condiviso'}</small></span><em className={plan?'active':'empty'}>{plan?'Attivo':'Da caricare'}</em><label>＋ {plan?'Aggiorna':'Carica'}<input type="file" accept=".pdf,image/*" onChange={e=>save(c.name,e.target.files?.[0]?.name||'Piano alimentare.pdf')}/></label></article>})}</div><div className="nutrition-disclaimer">Progressì organizza e condivide il piano alimentare. Non sostituisce il parere di un professionista sanitario.</div></section>}
function AthleteDiet({plan,go}:{plan?:DietPlan;go:(v:View)=>void}){return <section className="ath-home diet-page"><p className="date">PIANO ALIMENTARE</p><h1>La tua dieta</h1><p className="sub">Sempre disponibile, insieme alle indicazioni del professionista.</p>{plan?<><article className="diet-hero"><span>PIANO ATTIVO</span><i>PDF</i><h2>{plan.file.replace('.pdf','')}</h2><p>Aggiornato il {plan.updated} · valido fino al {plan.validUntil}</p><small>Preparato da {plan.author}</small><button onClick={()=>alert('Anteprima documento demo')}>Apri il piano <b>→</b></button></article><div className="meal-timeline"><h2>La tua giornata</h2>{[['08:00','Colazione','Yogurt greco, avena e frutta'],['11:00','Spuntino','Frutta fresca e mandorle'],['13:30','Pranzo','Riso, pollo e verdure'],['17:00','Pre-workout','Pane integrale e banana'],['20:30','Cena','Salmone, patate e verdure']].map(x=><article key={x[0]}><time>{x[0]}</time><i/><span><b>{x[1]}</b><small>{x[2]}</small></span></article>)}</div><button className="ask-diet" onClick={()=>go('messages')}>Hai un dubbio? Scrivi al PT →</button></>:<div className="empty-diet"><i>◇</i><h2>Nessun piano condiviso</h2><p>Quando il tuo PT caricherà un documento, lo troverai qui.</p></div>}<p className="nutrition-disclaimer">Il piano alimentare non sostituisce il parere di un professionista sanitario.</p></section>}
function MessagesPage({messages,send}:{messages:Message[];send:(text:string)=>void}){return <section className="ath-home messages-page"><p className="date">CONVERSAZIONE CON IL PT</p><h1>Messaggi</h1><p className="sub">Scrivi a Luca per spostare un allenamento, fare una domanda o lasciare un aggiornamento.</p><Conversation name="Luca Bianchi · Personal Trainer" role="athlete" messages={messages} send={send}/></section>}
function Conversation({name,role,messages,send}:{name:string;role:'pt'|'athlete';messages:Message[];send:(text:string)=>void}){const[text,setText]=useState('');const submit=()=>{if(!text.trim())return;send(text.trim());setText('')};return <section id="conversation" className="conversation"><header><i>{role==='pt'?name.split(' ').map(x=>x[0]).join('').slice(0,2):'LB'}</i><span><b>{name}</b><small><em/> Disponibile</small></span></header><div className="message-stream">{messages.map((m,i)=><div className={'message '+(m.from===role?'mine':'theirs')} key={i}><p>{m.text}</p><small>{m.time}</small></div>)}</div><div className="message-quick">{role==='pt'&&['Puoi spostare l’allenamento?','Come ti senti oggi?'].map(x=><button key={x} onClick={()=>setText(x)}>{x}</button>)}</div><form onSubmit={e=>{e.preventDefault();submit()}}><input value={text} onChange={e=>setText(e.target.value)} placeholder="Scrivi un messaggio…"/><button>Invia →</button></form></section>}
function AthleteHome({go,client,schedule}:{go:(v:View)=>void;client:Client;schedule:ScheduleState[]}){const skipped=schedule.filter(x=>x==='skipped').length;return <section className="ath-home"><p className="date">DOMENICA · 7 SETTEMBRE</p><h1>Ciao, Marco <span>👋</span></h1><p className="sub">Un sì alla volta, i progressi diventano visibili.</p>{skipped>0&&<button className="ath-alert" onClick={()=>go('calendar')}><i>!</i><span><b>Hai saltato {skipped} allenamento</b><small>Il tuo PT può vederlo · apri il calendario</small></span><em>→</em></button>}<article className="today-card"><div className="day-mark">2</div><p className="eyebrow">PROGRAMMA · {client.planned} GIORNI</p><h2>Allenamento giorno 2</h2><p>6 esercizi · circa 55 min</p><div className="exercise-line">Ordine consigliato, scelta libera degli esercizi</div><button className="start-btn" onClick={()=>go('picker')}>Apri allenamento <span>→</span></button><small>Questa settimana: {client.done} di {client.planned} completati</small></article><div className="ath-stats"><div><span>SETTIMANA</span><b>{client.done} / {client.planned}</b><small>giorni svolti</small></div><div><span>STREAK</span><b>5</b><small>settimane</small></div><div><span>SCORE</span><b>82</b><small>in crescita</small></div></div><div className="quick-links"><button onClick={()=>go('calendar')}><i>□</i><span><b>Calendario</b><small>Sposta o salta un giorno</small></span><em>→</em></button><button onClick={()=>go('progress')}><i>↗</i><span><b>Tutti i progressi</b><small>Storico, forza e costanza</small></span><em>→</em></button></div></section>}
function Calendar({days,schedule,setDays,setSchedule}:{days:string[];schedule:ScheduleState[];setDays:(x:string[])=>void;setSchedule:(x:ScheduleState[])=>void}){const all=['Lunedì','Martedì','Mercoledì','Giovedì','Venerdì','Sabato','Domenica'];const move=(i:number,val:string)=>{const next=[...days];next[i]=val;setDays(next)};const skip=(i:number)=>{const next=[...schedule];next[i]=next[i]==='skipped'?'planned':'skipped';setSchedule(next)};return <section className="ath-home calendar-page"><p className="date">CALENDARIO CONDIVISO CON IL PT</p><h1>La tua settimana</h1><p className="sub">Puoi spostare o saltare un allenamento. Il tuo PT vedrà subito ogni cambiamento.</p><div className="week-strip">{all.map(d=>{const idx=days.indexOf(d),state=idx>=0?schedule[idx]:undefined;return <div className={state||''} key={d}><span>{d.slice(0,3)}</span><b>{idx+1||'·'}</b></div>})}</div><div className="calendar-list enhanced">{days.map((d,i)=><article className={schedule[i]} key={i}><i>{schedule[i]==='completed'?'✓':schedule[i]==='skipped'?'×':i+1}</i><div><b>Allenamento giorno {i+1}</b><small>{schedule[i]==='completed'?'Completato':schedule[i]==='skipped'?'Saltato · PT informato':'6 esercizi · circa 55 min'}</small></div><select disabled={schedule[i]==='completed'} value={d} onChange={e=>move(i,e.target.value)}>{all.map(x=><option key={x}>{x}</option>)}</select>{schedule[i]!=='completed'&&<button className="skip-btn" onClick={()=>skip(i)}>{schedule[i]==='skipped'?'Ripristina':'Salta'}</button>}</article>)}</div><div className="calendar-legend"><span><i className="completed"/>Completato</span><span><i className="planned"/>Programmato</span><span><i className="skipped"/>Saltato e segnalato</span></div></section>}
function AthleteSheet({go}:{go:(v:View)=>void}){return <section className="ath-home sheet-page"><p className="date">SCHEDA ATTIVA</p><h1>Total Body · Base</h1><p className="sub">3 giorni a settimana · aggiornata dal tuo PT</p><div className="sheet-days">{[1,2,3].map((d,i)=><article key={d}><div><i>{d}</i><span><b>Allenamento giorno {d}</b><small>{i===0?'Completato':i===1?'Prossimo':'Da fare'}</small></span></div><div className="sheet-exercises">{baseExercises.map((x,n)=><span key={x.name}><i>{x.icon}</i><small>{n+1}. {x.name}</small></span>)}</div>{i===1&&<button className="primary" onClick={()=>go('picker')}>Apri allenamento →</button>}</article>)}</div></section>}
function Picker({completed,choose,finish,go}:{completed:number[];choose:(i:number)=>void;finish:()=>void;go:(v:View)=>void}){return <main className="athlete-app"><header className="ath-head"><button className="circle-btn" onClick={()=>go('athlete-home')}>←</button><div><small>ALLENAMENTO GIORNO 2</small><b>{completed.length}/6 esercizi</b></div><button className="text-btn" onClick={()=>completed.length===6&&finish()}>{completed.length===6?'Termina':'In corso'}</button></header><section className="exercise-picker"><p className="eyebrow">ORDINE CONSIGLIATO · FLESSIBILE</p><h1>Scegli il prossimo esercizio</h1><p>Segui i numeri oppure passa a un altro attrezzo se quello consigliato è occupato.</p><div className="exercise-grid">{baseExercises.map((x,i)=><button className={completed.includes(i)?'done':''} onClick={()=>!completed.includes(i)&&choose(i)} key={x.name}><span className="order-number">{i+1}</span>{x.group&&<span className="group-badge">{x.group}</span>}<i>{completed.includes(i)?'✓':x.icon}</i><b>{x.name}</b><small>{completed.includes(i)?'Completato':`${x.sets} × ${x.reps}`}</small></button>)}</div>{completed.length===6&&<button className="primary wide" onClick={finish}>Termina allenamento</button>}</section></main>}
function Workout({current,partner,setNo,kg,reps,setKg,setReps,complete,seconds,skip,go}:{current:Exercise;partner?:Exercise;setNo:number;kg:number;reps:number;setKg:(x:number)=>void;setReps:(x:number)=>void;complete:(rest:number)=>void;seconds:number;skip:()=>void;go:(v:View)=>void}){const[rest,setRest]=useState(120);return <main className="athlete-app workout-screen"><header className="ath-head"><button className="circle-btn" onClick={()=>go('picker')}>←</button><div><small>ALLENAMENTO GIORNO 2</small><b>Serie {setNo} di {current.sets}</b></div><button className="text-btn" onClick={()=>go('picker')}>Cambia</button></header><section className="set-stage"><div className="exercise-symbol">{current.icon}</div>{current.group&&<span className="workout-group">{current.group}</span>}<h1>{current.name}</h1><p>Target · {current.sets} × {current.reps}</p>{partner&&<div className="superset-next"><span>SUBITO DOPO</span><b>{partner.name}</b><small>Transizione rapida · 15 secondi</small></div>}<div className="technique-tip"><i>◎</i><span><small>RICORDA</small><b>{exerciseTips[current.name]||'Movimento controllato e respirazione regolare.'}</b></span></div><div className="set-dots">{[1,2,3].map(n=><i className={n<setNo?'checked':n===setNo?'active':''} key={n}>{n<setNo?'✓':n}</i>)}</div><div className="last-time"><span>ULTIMA VOLTA</span><b>{current.kg} kg × {current.reps}</b></div><div className="steppers"><Stepper label="CARICO" value={kg} unit="kg" step={2.5} set={setKg}/><Stepper label="RIPETIZIONI" value={reps} unit="reps" step={1} set={setReps}/></div>{!partner&&<div className="rest-choice"><span><small>RECUPERO DOPO LA SERIE</small><b>{Math.floor(rest/60)}:{String(rest%60).padStart(2,'0')} min</b></span><div><button onClick={()=>setRest(Math.max(30,rest-15))}>−15s</button><button onClick={()=>setRest(Math.min(300,rest+15))}>+15s</button></div></div>}<button className={'complete-btn '+(partner?'superset-action':'')} onClick={()=>complete(rest)}>✓ {partner?`Completa e passa a ${partner.name}`:'Conferma serie e avvia recupero'}</button></section>{seconds>0&&<div className={'timer '+(current.group?'superset-timer':'')}><div><span>{current.group?'TRANSIZIONE SUPERSET':'RECUPERO IN CORSO'}</span><strong>{String(Math.floor(seconds/60)).padStart(2,'0')}:{String(seconds%60).padStart(2,'0')}</strong></div><button onClick={skip}>{current.group?'Inizia subito':'Salta'}</button></div>}</main>}
function Stepper({label,value,unit,step,set}:{label:string;value:number;unit:string;step:number;set:(x:number)=>void}){return <div className="stepper"><span>{label}</span><div><button onClick={()=>set(Math.max(0,value-step))}>−</button><b>{value}<small>{unit}</small></b><button onClick={()=>set(value+step)}>+</button></div></div>}
function Progress(){return <section className="ath-home progress-page"><p className="date">STORICO COMPLETO</p><h1>Tutti i tuoi progressi</h1><div className="progress-score"><div><span>PROGRESS SCORE <small>DEMO</small></span><b>82<em>/100</em></b><p>↑ 10 punti in 4 settimane</p></div><Bars/></div><div className="trend-cards"><div><span>FORZA</span><b>+8,3%</b><small>8 settimane</small></div><div><span>VOLUME</span><b>+12,1%</b><small>8 settimane</small></div><div><span>COSTANZA</span><b>92%</b><small>11/12 workout</small></div></div><History/><h2>Progressi per esercizio</h2>{[['Chest press','+7%','72,5 kg'],['Squat','+11%','112,5 kg'],['Lat machine','+6%','62,5 kg'],['Military press','+4%','42,5 kg'],['Tricipiti ai cavi','+9%','30 kg'],['Bicipiti ai cavi','+5%','25 kg']].map(x=><div className="exercise-progress" key={x[0]}><div><b>{x[0]}</b><small>Miglior carico · {x[2]}</small></div><Spark/><strong>↑ {x[1]}</strong></div>)}</section>}
function Summary({go}:{go:(v:View)=>void}){return <main className="summary-screen"><div className="success">✓</div><p className="eyebrow">ALLENAMENTO COMPLETATO</p><h1>Un altro sì ai tuoi progressi.</h1><p>Hai completato tutti gli esercizi del giorno 2.</p><div className="summary-grid"><div><span>DURATA</span><b>54 min</b></div><div><span>VOLUME</span><b>7.840 kg</b></div><div><span>SERIE</span><b>18/18</b></div><div><span>PR</span><b>2</b></div></div><button className="primary wide" onClick={()=>go('progress')}>Vedi tutti i progressi →</button></main>}
function Bars(){return <div className="bars">{[32,38,44,42,55,61,68,79].map((h,i)=><i key={i} style={{height:h}}/>)}</div>}
function Spark(){return <div className="spark">{[12,20,17,28,25,38,42,50].map((h,i)=><i key={i} style={{height:h/2}}/>)}</div>}
